    "oeaH": "health_certificate_document_number",
    "qire": "health_certificate_issuing_authority",
    "m6sx": "health_certificate_place_of_issue",
    "mTnb": "health_certificate_date_of_issue",
    "rLtb": "health_certificate_date_of_expiry",
    "6Lxr": "health_certificate_notes",

    "couc": "passport_file_upload",
    "8P7s": "passport_document_number",
    "nuRr": "passport_issuing_authority",
    "2A52": "passport_place_of_issue",
    "4Jsq": "passport_date_of_issue",
    "gho6": "passport_date_of_expiry",
    "s1Xy": "passport_notes",

    "fmfU": "id_card_file_upload",
    "9HJb": "id_card_document_number",
    "xjzj": "id_card_issuing_authority",
    "gdEy": "id_card_place_of_issue",
    "ssVb": "id_card_date_of_issue",
    "iqUf": "id_card_date_of_expiry",
    "aakM": "id_card_notes",

    "iMXW": "driving_license_file_upload",
    "vfQj": "driving_license_document_number",
    "mGdT": "driving_license_issuing_authority",
    "bMYb": "driving_license_place_of_issue",
    "uKdZ": "driving_license_date_of_issue",
    "cCiZ": "driving_license_date_of_expiry",
    "9Rzj": "driving_license_notes",

    "c7Z2": "non_duplication_certificate_file_upload",
    "18YW": "non_duplication_certificate_document_number",
    "jDfS": "non_duplication_certificate_issuing_authority",
    "qFjp": "non_duplication_certificate_place_of_issue",
    "jsEL": "non_duplication_certificate_date_of_issue",
    "miDH": "non_duplication_certificate_date_of_expiry",
    "gwFN": "non_duplication_certificate_notes",

    "5U3s": "account_number",
    "32uF": "bank_branch",
    "tJF4": "bank_name",
    "pvXT": "iban",
    "7jUn": "bank_notes",
    "jpNf": "form_notes",
};

function isObject(value) {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

function firstNonEmpty(...values) {
    for (const value of values) {
        if (value !== undefined && value !== null && value !== "") {
            return value;
        }
    }
    return null;
}

function normalizeScalar(value) {
    if (Array.isArray(value)) {
        return value.length ? normalizeScalar(value[0]) : null;
    }

    if (isObject(value)) {
        if ("odoo_id" in value) return normalizeScalar(value.odoo_id);
        if ("value" in value) return normalizeScalar(value.value);
        if ("answer" in value) return normalizeScalar(value.answer);
        if ("text" in value) return normalizeScalar(value.text);
        if ("label" in value) return normalizeScalar(value.label);
        if ("id" in value) return normalizeScalar(value.id);
        if ("recordID" in value) return normalizeScalar(value.recordID);
    }

    if (value === undefined || value === null || value === "") return null;

    return String(value);
}

function normalizeBooleanFlag(value) {
    const scalar = normalizeScalar(value);
    if (scalar === null) return false;

    return ["1", "true", "yes", "y", "on"].includes(
        String(scalar).trim().toLowerCase()
    );
}

function normalizeUrlParameters(raw) {
    if (!raw) return {};

    if (isObject(raw)) {
        const result = {};
        for (const [key, value] of Object.entries(raw)) {
            if (!IGNORED_URL_PARAMETER_NAMES.has(String(key))) {
                result[key] = normalizeScalar(value);
            }
        }
        return result;
    }

    if (Array.isArray(raw)) {
        const result = {};

        for (const item of raw) {
            if (!isObject(item)) continue;

            const key = firstNonEmpty(
                item.name,
                item.key,
                item.id,
                item.field,
                item.parameter
            );

            if (!key) continue;

            if (IGNORED_URL_PARAMETER_NAMES.has(String(key))) continue;

            result[String(key)] = normalizeScalar(
                firstNonEmpty(item.value, item.answer, item.text)
            );
        }

        return result;
    }

    return {};
}

function getQuestionValue(question) {
    if (!isObject(question)) return null;

    return firstNonEmpty(
        question.value,
        question.answer,
        question.answers,
        question.response,
        question.text,
        question.files,
        question.file,
        question.url
    );
}

function questionLooksLikeFile(question) {
    if (!isObject(question)) return false;

    const type = normalizeScalar(question.type);
    if (type && type.toLowerCase().includes("file")) return true;

    const value = getQuestionValue(question);

    if (Array.isArray(value)) {
        return value.some((entry) => isObject(entry) && (
            "url" in entry ||
            "downloadUrl" in entry ||
            "filename" in entry ||
            "fileName" in entry ||
            "name" in entry
        ));
    }

    if (isObject(value)) {
        return (
            "url" in value ||
            "downloadUrl" in value ||
            "filename" in value ||
            "fileName" in value ||
            "name" in value
        );
    }

    return false;
}

function normalizeFileEntries(value) {
    if (!value) return [];

    const rawEntries = Array.isArray(value) ? value : [value];

    return rawEntries
        .filter((entry) => entry !== undefined && entry !== null && entry !== "")
        .map((entry) => {
            let normalized;

            if (typeof entry === "string") {
                normalized = {
                    url: entry,
                    fileName: null,
                    mimeType: null,
                    size: null,
                };
            } else if (isObject(entry)) {
                normalized = {
                    url: firstNonEmpty(entry.url, entry.downloadUrl, entry.href, entry.link),
                    fileName: firstNonEmpty(entry.filename, entry.fileName, entry.name),
                    mimeType: firstNonEmpty(entry.mimeType, entry.mimetype, entry.type),
                    size: firstNonEmpty(entry.size, entry.sizeBytes, entry.fileSize),
                };
            } else {
                normalized = {
                    url: null,
                    fileName: null,
                    mimeType: null,
                    size: null,
                };
            }

            if (CONFIG.includeDebugPayload) {
                normalized.raw = entry;
            }

            return normalized;
        });
}

function normalizeQuestions(rawQuestions) {
    const questions = Array.isArray(rawQuestions) ? rawQuestions : [];

    const byId = {};
    const byName = {};
    const byCanonicalName = {};
    const byOriginalName = {};
    const byLabel = {};
    const filesByName = {};

    for (const question of questions) {
        if (!isObject(question)) continue;

        const id = firstNonEmpty(question.id, question.questionId, question.fieldId);
        const originalName = firstNonEmpty(question.name, question.key, question.slug);
        const canonicalName = id && FIELD_ID_TO_CANONICAL_NAME[id]
            ? FIELD_ID_TO_CANONICAL_NAME[id]
            : originalName;

        const label = firstNonEmpty(question.label, question.question, question.title);
        const value = getQuestionValue(question);
        const normalizedValue = normalizeScalar(value);
        const isFile = questionLooksLikeFile(question);

        const normalizedQuestion = {
            id,
            name: canonicalName,
            canonicalName,
            originalName,
            label,
            type: firstNonEmpty(question.type, question.fieldType),
            value,
            normalizedValue,
            isFile,
            files: isFile ? normalizeFileEntries(value) : [],
            raw: question,
        };

        if (id) byId[String(id)] = normalizedQuestion;
        if (canonicalName) {
            byName[String(canonicalName)] = normalizedQuestion;
            byCanonicalName[String(canonicalName)] = normalizedQuestion;
        }
        if (originalName) byOriginalName[String(originalName)] = normalizedQuestion;
        if (label) byLabel[String(label)] = normalizedQuestion;

        if (canonicalName && normalizedQuestion.isFile) {
            filesByName[String(canonicalName)] = normalizedQuestion.files;
        }
    }

    return {
        raw: questions,
        byId,
        byName,
        byCanonicalName,
        byOriginalName,
        byLabel,
        filesByName,
    };
}

function getQuestionByName(questionIndex, name) {
    if (!questionIndex) return null;

    if (questionIndex.byCanonicalName && questionIndex.byCanonicalName[name]) {
        return questionIndex.byCanonicalName[name];
    }

    if (questionIndex.byName && questionIndex.byName[name]) {
        return questionIndex.byName[name];
    }

    return null;
}

function getQuestionScalar(questionIndex, name) {
    const question = getQuestionByName(questionIndex, name);
    return question ? question.normalizedValue : null;
}

function getQuestionFiles(questionIndex, name) {
    const question = getQuestionByName(questionIndex, name);
    return question && Array.isArray(question.files) ? question.files : [];
}

function collectPrefixedScalarFields(prefix, questionIndex, uploadFieldName) {
    const scalarFields = {};
    const names = Object.keys(questionIndex.byName || {})
        .filter((key) => key === prefix || key.startsWith(`${prefix}_`));

    for (const fieldName of names) {
        if (fieldName === uploadFieldName) continue;
        if (isSectionRoutingField(prefix, fieldName)) continue;

        scalarFields[fieldName] = getQuestionScalar(questionIndex, fieldName);
    }

    return scalarFields;
}

function addKnownNonPrefixedFields(prefix, questionIndex, scalarFields) {
    if (prefix === "birth_certificate") {
        for (const fieldName of ["date_of_birth", "place_of_birth", "country_of_birth"]) {
            scalarFields[fieldName] = getQuestionScalar(questionIndex, fieldName);
        }
    }

    if (prefix === "family_status") {
        for (const fieldName of [
            "family_paper_number",
            "family_reference_number",
            "next_of_kin_name",
            "next_of_kin_phone",
        ]) {
            scalarFields[fieldName] = getQuestionScalar(questionIndex, fieldName);
        }
    }

    if (prefix === "health_certificate") {
        scalarFields.blood_type = getQuestionScalar(questionIndex, "blood_type");
    }

    if (prefix === "bank_information") {
        for (const fieldName of [
            "bank_name",
            "bank_branch",
            "account_number",
            "iban",
            "bank_notes",
        ]) {
            scalarFields[fieldName] = getQuestionScalar(questionIndex, fieldName);
        }
    }

    return scalarFields;
}

function buildSection(prefix, urlParams, questionIndex) {
    const show = normalizeBooleanFlag(urlParams[`${prefix}_show`]);

    const routing = {
        show,
        requestLineId: normalizeScalar(urlParams[`${prefix}_request_line_id`]),
        checklistLineId: normalizeScalar(urlParams[`${prefix}_checklist_line_id`]),
        documentTypeId: normalizeScalar(urlParams[`${prefix}_document_type_id`]),
        documentCode: normalizeScalar(urlParams[`${prefix}_document_code`]),
    };

    const uploadFieldName = prefix === "bank_information"
        ? null
        : `${prefix}_file_upload`;

    const files = uploadFieldName
        ? getQuestionFiles(questionIndex, uploadFieldName)
        : [];

    let scalarFields = collectPrefixedScalarFields(prefix, questionIndex, uploadFieldName);
    scalarFields = addKnownNonPrefixedFields(prefix, questionIndex, scalarFields);

    const hasStructuredData = Object.values(scalarFields).some((value) => {
        return value !== undefined && value !== null && value !== "";
    });

    return {
        prefix,
        routing,
        uploadFieldName,
        files,
        scalarFields,
        hasFiles: files.length > 0,
        hasStructuredData,
        hasPayload: files.length > 0 || hasStructuredData,
        rawStatus: show ? "requested" : "skipped_not_requested",
    };
}

function getPayloadFromItem(item) {
    const json = item && item.json ? item.json : {};

    if (json.body && isObject(json.body)) return json.body;

    return json;
}

function buildRequestEnvelope(urlParameters) {
    return {
        odooRequestId: normalizeScalar(urlParameters.odoo_request_id),
        odooApplicantId: normalizeScalar(urlParameters.odoo_applicant_id),
        odooChecklistId: normalizeScalar(urlParameters.odoo_checklist_id),
        requestReference: normalizeScalar(urlParameters.request_reference),
        candidateName: normalizeScalar(urlParameters.candidate_name),
        candidateEmail: normalizeScalar(urlParameters.candidate_email),
        tokenReference: normalizeScalar(urlParameters.token_reference),
        expiresAt: normalizeScalar(urlParameters.expires_at),
        formBaseUrl: normalizeScalar(urlParameters.form_base_url),
        state: normalizeScalar(urlParameters.state),
        sentAt: normalizeScalar(urlParameters.sent_at),
        lastResponseAt: normalizeScalar(urlParameters.last_response_at),
    };
}

function buildValidationHints(payload, submission, request) {
    const validationHints = [];

    if (payload.formId !== EXPECTED_FORM_ID) {
        validationHints.push({
            level: "error",
            code: "unexpected_form_id",
            message: `Expected formId ${EXPECTED_FORM_ID}, received ${payload.formId || "empty"}.`,
        });
    }

    if (!submission.submissionId) {
        validationHints.push({
            level: "error",
            code: "missing_submission_id",
            message: "Fillout submissionId is missing.",
        });
    }

    if (!submission.urlParameters) {
        validationHints.push({
            level: "error",
            code: "missing_url_parameters",
            message: "Fillout urlParameters object is missing.",
        });
    }

    for (const key of [
        "odooRequestId",
        "odooApplicantId",
        "odooChecklistId",
        "tokenReference",
    ]) {
        if (!request[key]) {
            validationHints.push({
                level: "error",
                code: `missing_${key}`,
                message: `Request envelope value is missing: ${key}.`,
            });
        }
    }

    return validationHints;
}

function parseItem(item, itemIndex) {
    const payload = getPayloadFromItem(item);
    const submission = payload.submission || {};
    const urlParameters = normalizeUrlParameters(submission.urlParameters);
    const questionIndex = normalizeQuestions(submission.questions);
    const request = buildRequestEnvelope(urlParameters);
    const formNotes = getQuestionScalar(questionIndex, "form_notes");

    const sections = PUBLIC_SECTION_PREFIXES.map((prefix) => {
        return buildSection(prefix, urlParameters, questionIndex);
    });

    const requestedSections = sections.filter((section) => section.routing.show);
    const sectionsWithPayload = sections.filter((section) => section.hasPayload);
    const validationHints = buildValidationHints(payload, submission, request);

    const parsed = {
        parser: {
            module: "required_document_writeback_parse_payload.js",
            version: CONFIG.parserVersion,
            workflow: CONFIG.workflow,
            itemIndex,
            parsedAt: new Date().toISOString(),
            compactOutput: !CONFIG.includeDebugPayload,
        },
        form: {
            id: payload.formId || null,
            name: payload.formName || null,
            expectedFormId: EXPECTED_FORM_ID,
            isExpectedForm: payload.formId === EXPECTED_FORM_ID,
        },
        submission: {
            id: submission.submissionId || null,
            submissionTime: submission.submissionTime || null,
            lastUpdatedAt: submission.lastUpdatedAt || null,
        },
        request,
        formNotes,
        urlParameters,
        sections,
        constants: {
            publicSectionPrefixes: PUBLIC_SECTION_PREFIXES,
            nonPublicSectionPrefixes: NON_PUBLIC_SECTION_PREFIXES,
            fieldIdMapVersion: "6C-2A",
            compactParserVersion: CONFIG.parserVersion,
        },
        summary: {
            questionCount: questionIndex.raw.length,
            urlParameterCount: Object.keys(urlParameters).length,
            sectionCount: sections.length,
            requestedSectionCount: requestedSections.length,
            sectionsWithPayloadCount: sectionsWithPayload.length,
            requestedPrefixes: requestedSections.map((section) => section.prefix),
            payloadPrefixes: sectionsWithPayload.map((section) => section.prefix),
            validationHintCount: validationHints.length,
        },
        validationHints,
    };

    if (CONFIG.includeDebugPayload) {
        parsed.questionIndex = questionIndex;
        parsed.raw = {
            payload,
        };
    }

    return parsed;
}

const inputItems = $input.all();

return inputItems.map((item, index) => {
    return {
        json: parseItem(item, index),
    };
});

/**
 * MCEP / Marsellia — Required Document Writeback
 * Workflow: Marsellia | Recruitment | Required Document Submission
 * Node: Validate Odoo Envelope
 * Module: required_document_writeback_validate_envelope.js
 *
 * Pass 6C-3A rate-limit-safe variant:
 * - Uses only two Odoo HTTP lookups:
 *   1) Lookup Odoo Request
 *   2) Lookup Odoo Request Lines
 * - Does not call checklist lines separately.
 *
 * Related contract:
 * docs/modules/hr_recruitment_custom/n8n_required_document_writeback_contract.md
 */

const CONFIG = {
  moduleVersion: "6C-3A",
  probeModeAllowPrepared: true,
  nodeNames: {
    parsePayload: "Parse Fillout Payload",
    lookupRequest: "Lookup Odoo Request",
    lookupRequestLines: "Lookup Odoo Request Lines",
  },
  allowedRequestStatesForProbe: ["sent", "prepared"],
  allowedRequestStatesProduction: ["sent"],
  allowedRequestLineStates: ["requested", "submitted"],
};

function isObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function normalizeScalar(value) {
  if (Array.isArray(value)) {
    return value.length ? normalizeScalar(value[0]) : null;
  }

  if (isObject(value)) {
    if ("id" in value) return normalizeScalar(value.id);
    if ("value" in value) return normalizeScalar(value.value);
    if ("odoo_id" in value) return normalizeScalar(value.odoo_id);
  }

  if (value === undefined || value === null || value === "") return null;

  return String(value);
}

function extractOdooId(value) {
  return normalizeScalar(value);
}

function sameId(left, right) {
  const a = extractOdooId(left);
  const b = extractOdooId(right);
  return a !== null && b !== null && String(a) === String(b);
}

function normalizeBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;

  const scalar = normalizeScalar(value);
  if (scalar === null) return false;

  return ["1", "true", "yes", "y", "on"].includes(
    String(scalar).trim().toLowerCase()
  );
}

function getNodeItems(nodeName) {
  try {
    if (typeof $items === "function") {
      return $items(nodeName) || [];
    }
  } catch (error) {
    return [];
  }

  return [];
}

function normalizeRecord(record) {
  if (!isObject(record)) return null;

  if (record.json && isObject(record.json)) return normalizeRecord(record.json);
  if (record.record && isObject(record.record)) return normalizeRecord(record.record);

  return record;
}

function flattenRecordsFromItems(items) {
  const records = [];

  for (const item of items || []) {
    const json = item && item.json ? item.json : item;

    if (Array.isArray(json)) {
      for (const entry of json) {
        const normalized = normalizeRecord(entry);
        if (normalized) records.push(normalized);
      }
      continue;
    }

    if (isObject(json) && Array.isArray(json.records)) {
      for (const entry of json.records) {
        const normalized = normalizeRecord(entry);
        if (normalized) records.push(normalized);
      }
      continue;
    }

    if (isObject(json) && Array.isArray(json.data)) {
      for (const entry of json.data) {
        const normalized = normalizeRecord(entry);
        if (normalized) records.push(normalized);
      }
      continue;
    }

    if (isObject(json) && Array.isArray(json.result)) {
      for (const entry of json.result) {
        const normalized = normalizeRecord(entry);
        if (normalized) records.push(normalized);
      }
      continue;
    }

    const normalized = normalizeRecord(json);
    if (normalized) records.push(normalized);
  }

  return records;
}

function getRecordsFromNode(nodeName) {
  return flattenRecordsFromItems(getNodeItems(nodeName));
}

function getParsedPayload() {
  const parsedItems = getNodeItems(CONFIG.nodeNames.parsePayload);

  if (parsedItems.length) {
    const first = parsedItems[0];
    return first && first.json ? first.json : first;
  }

  const inputItems = $input.all();
  if (inputItems.length) {
    const first = inputItems[0];
    return first && first.json ? first.json : first;
  }

  return {};
}

function byId(records) {
  const result = {};

  for (const record of records || []) {
    const id = extractOdooId(record.id);
    if (id !== null) {
      result[String(id)] = record;
    }
  }

  return result;
}

function parseDateTime(value) {
  const scalar = normalizeScalar(value);
  if (!scalar) return null;

  let text = String(scalar).trim();

  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}/.test(text)) {
    text = text.replace(" ", "T");
  }

  text = text.replace(/(\.\d{3})\d+/, "$1");

  if (/^\d{4}-\d{2}-\d{2}T/.test(text) && !/(Z|[+-]\d{2}:?\d{2})$/.test(text)) {
    text += "Z";
  }

  const date = new Date(text);
  if (Number.isNaN(date.getTime())) return null;

  return date;
}

function makeIssue(level, code, message, context = {}) {
  return { level, code, message, context };
}

function getAllowedRequestStates() {
  return CONFIG.probeModeAllowPrepared
    ? CONFIG.allowedRequestStatesForProbe
    : CONFIG.allowedRequestStatesProduction;
}

function validateEnvelope(parsed, requestRecord, now) {
  const errors = [];
  const warnings = [];
  const request = parsed.request || {};

  for (const hint of parsed.validationHints || []) {
    if (hint.level === "error") {
      errors.push(makeIssue("error", hint.code, hint.message));
    } else {
      warnings.push(makeIssue("warning", hint.code, hint.message));
    }
  }

  if (!requestRecord) {
    errors.push(makeIssue(
      "error",
      "odoo_request_not_found",
      "Odoo submission request was not found from odoo_request_id.",
      { odooRequestId: request.odooRequestId }
    ));

    return {
      status: "invalid",
      errors,
      warnings,
      requestRecordFound: false,
    };
  }

  if (!sameId(requestRecord.id, request.odooRequestId)) {
    errors.push(makeIssue(
      "error",
      "request_id_mismatch",
      "Odoo request ID does not match parsed request ID."
    ));
  }

  if (normalizeScalar(requestRecord.x_token_reference) !== normalizeScalar(request.tokenReference)) {
    errors.push(makeIssue(
      "error",
      "token_reference_mismatch",
      "Token reference does not match the Odoo request."
    ));
  }

  if (!sameId(requestRecord.x_applicant_id, request.odooApplicantId)) {
    errors.push(makeIssue(
      "error",
      "applicant_id_mismatch",
      "Applicant ID does not match the Odoo request."
    ));
  }

  if (!sameId(requestRecord.x_checklist_id, request.odooChecklistId)) {
    errors.push(makeIssue(
      "error",
      "checklist_id_mismatch",
      "Checklist ID does not match the Odoo request."
    ));
  }

  const requestState = normalizeScalar(requestRecord.x_state);
  const allowedStates = getAllowedRequestStates();

  if (!allowedStates.includes(requestState)) {
    errors.push(makeIssue(
      "error",
      "invalid_request_state",
      "Odoo request is not in an allowed state for writeback.",
      { state: requestState, allowedStates }
    ));
  }

  if (requestState === "prepared" && CONFIG.probeModeAllowPrepared) {
    warnings.push(makeIssue(
      "warning",
      "prepared_state_allowed_for_probe",
      "Prepared request state is allowed during the Pass 6C probe. Production should require sent."
    ));
  }

  const expiry = parseDateTime(requestRecord.x_expires_at || request.expiresAt);

  if (!expiry) {
    errors.push(makeIssue(
      "error",
      "missing_or_invalid_expiry",
      "Request expiry is missing or invalid."
    ));
  } else if (expiry.getTime() < now.getTime()) {
    errors.push(makeIssue(
      "error",
      "request_expired",
      "Submission request has expired.",
      { expiresAt: expiry.toISOString() }
    ));
  }

  return {
    status: errors.length ? "invalid" : (warnings.length ? "valid_with_warnings" : "valid"),
    errors,
    warnings,
    requestRecordFound: true,
    requestState,
    allowedStates,
    expiresAt: expiry ? expiry.toISOString() : null,
  };
}

function validateSection(section, parsed, requestLineById) {
  const errors = [];
  const warnings = [];

  if (!section.routing || !section.routing.show) {
    return {
      ...section,
      validation: {
        status: "skipped_not_requested",
        isValidForWriteback: false,
        errors,
        warnings,
      },
    };
  }

  const request = parsed.request || {};
  const routing = section.routing;

  const requestLineId = normalizeScalar(routing.requestLineId);
  const checklistLineId = normalizeScalar(routing.checklistLineId);
  const documentTypeId = normalizeScalar(routing.documentTypeId);
  const documentCode = normalizeScalar(routing.documentCode);

  if (!requestLineId) {
    errors.push(makeIssue("error", "missing_request_line_id", "Requested section is missing request line ID."));
  }

  if (!checklistLineId) {
    errors.push(makeIssue("error", "missing_checklist_line_id", "Requested section is missing checklist line ID."));
  }

  if (!documentTypeId) {
    errors.push(makeIssue("error", "missing_document_type_id", "Requested section is missing document type ID."));
  }

  if (!documentCode) {
    errors.push(makeIssue("error", "missing_document_code", "Requested section is missing document code."));
  }

  const requestLine = requestLineId ? requestLineById[String(requestLineId)] : null;

  if (!requestLine) {
    errors.push(makeIssue(
      "error",
      "request_line_not_found",
      "Odoo request line was not found.",
      { requestLineId }
    ));
  }

  if (requestLine) {
    if (!sameId(requestLine.x_request_id, request.odooRequestId)) {
      errors.push(makeIssue(
        "error",
        "request_line_request_mismatch",
        "Request line does not belong to the Odoo request."
      ));
    }

    if (!sameId(requestLine.x_applicant_id, request.odooApplicantId)) {
      errors.push(makeIssue(
        "error",
        "request_line_applicant_mismatch",
        "Request line applicant does not match request envelope."
      ));
    }

    if (!sameId(requestLine.x_checklist_id, request.odooChecklistId)) {
      errors.push(makeIssue(
        "error",
        "request_line_checklist_mismatch",
        "Request line checklist does not match request envelope."
      ));
    }

    if (!sameId(requestLine.x_checklist_line_id, checklistLineId)) {
      errors.push(makeIssue(
        "error",
        "request_line_checklist_line_mismatch",
        "Request line checklist line does not match section routing."
      ));
    }

    if (!sameId(requestLine.x_document_type_id, documentTypeId)) {
      errors.push(makeIssue(
        "error",
        "request_line_document_type_mismatch",
        "Request line document type does not match section routing."
      ));
    }

    if (normalizeScalar(requestLine.x_document_code) !== documentCode) {
      errors.push(makeIssue(
        "error",
        "request_line_document_code_mismatch",
        "Request line document code does not match section routing."
      ));
    }

    const requestLineState = normalizeScalar(requestLine.x_state);

    if (!CONFIG.allowedRequestLineStates.includes(requestLineState)) {
      errors.push(makeIssue(
        "error",
        "invalid_request_line_state",
        "Request line is not in an allowed state for writeback.",
        { state: requestLineState, allowedStates: CONFIG.allowedRequestLineStates }
      ));
    }

    if (!normalizeBoolean(requestLine.x_public_request_enabled)) {
      errors.push(makeIssue(
        "error",
        "request_line_not_public",
        "Request line is not public request enabled."
      ));
    }
  }

  const status = errors.length ? "invalid" : (warnings.length ? "valid_with_warnings" : "valid");

  return {
    ...section,
    odoo: {
      requestLine,
    },
    validation: {
      status,
      isValidForWriteback: !errors.length,
      errors,
      warnings,
    },
  };
}

const parsed = getParsedPayload();

const requestRecords = getRecordsFromNode(CONFIG.nodeNames.lookupRequest);
const requestLineRecords = getRecordsFromNode(CONFIG.nodeNames.lookupRequestLines);

const requestById = byId(requestRecords);
const requestLineById = byId(requestLineRecords);

const requestId = parsed.request ? parsed.request.odooRequestId : null;
const requestRecord = requestId ? requestById[String(requestId)] : null;

const now = new Date();

const envelope = validateEnvelope(parsed, requestRecord, now);

const validatedSections = (parsed.sections || []).map((section) => {
  return validateSection(section, parsed, requestLineById);
});

const requestedSections = validatedSections.filter((section) => section.routing && section.routing.show);
const validRequestedSections = requestedSections.filter((section) => section.validation && section.validation.isValidForWriteback);
const invalidRequestedSections = requestedSections.filter((section) => section.validation && section.validation.status === "invalid");

const envelopeValid = envelope.status === "valid" || envelope.status === "valid_with_warnings";
const canProceed = envelopeValid && validRequestedSections.length > 0;

let status = "invalid";
if (canProceed && invalidRequestedSections.length) {
  status = "partial_valid";
} else if (canProceed) {
  status = "valid";
}

return [
  {
    json: {
      ...parsed,
      sections: validatedSections,
      odooLookup: {
        requestRecordFound: !!requestRecord,
        requestRecord,
        requestRecordCount: requestRecords.length,
        requestLineRecordCount: requestLineRecords.length,
      },
      validation: {
        module: "required_document_writeback_validate_envelope.js",
        version: CONFIG.moduleVersion,
        workflow: "Marsellia | Recruitment | Required Document Submission",
        checkedAt: now.toISOString(),
        probeModeAllowPrepared: CONFIG.probeModeAllowPrepared,
        status,
        canProceed,
        envelope,
        sectionSummary: {
          requestedSectionCount: requestedSections.length,
          validRequestedSectionCount: validRequestedSections.length,
          invalidRequestedSectionCount: invalidRequestedSections.length,
          validPrefixes: validRequestedSections.map((section) => section.prefix),
          invalidPrefixes: invalidRequestedSections.map((section) => section.prefix),
        },
      },
    },
  },
];

/**
 * MCEP / Marsellia — Required Document Writeback
 * Workflow: Marsellia | Recruitment | Required Document Submission
 * Node: Build Writeback Items
 * Module: required_document_writeback_build_section_items.js
 *
 * Pass 6C-5B:
 * - Builds compact writeback item(s) from validated envelope output.
 * - Emits all valid requested sections.
 * - No downloads.
 * - No Odoo writes.
 *
 * Input:
 * - Output from Validate Odoo Envelope.
 *
 * Output:
 * - One compact n8n item per valid requested section with payload.
 */

const CONFIG = {
    moduleVersion: "6C-5B",
    workflow: "Marsellia | Recruitment | Required Document Submission",
    probeOnlyPrefix: null,
    sourceSystem: "fillout_zite",
};

function isObject(value) {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

function cleanString(value) {
    if (value === undefined || value === null) return null;
    const text = String(value).trim();
    return text || null;
}

function toInt(value) {
    const text = cleanString(value);
    if (!text) return null;
    const parsed = Number.parseInt(text, 10);
    return Number.isFinite(parsed) ? parsed : null;
}

function normalizeOdooDatetime(value) {
    const text = cleanString(value);
    if (!text) return null;

    const date = new Date(text);
    if (Number.isNaN(date.getTime())) return null;

    const pad = (number) => String(number).padStart(2, "0");

    return [
        date.getUTCFullYear(),
        pad(date.getUTCMonth() + 1),
        pad(date.getUTCDate()),
    ].join("-") + " " + [
        pad(date.getUTCHours()),
        pad(date.getUTCMinutes()),
        pad(date.getUTCSeconds()),
    ].join(":");
}

function compactObject(obj) {
    return Object.fromEntries(
        Object.entries(obj).filter(([, value]) => {
            if (value === undefined || value === null) return false;
            if (typeof value === "string" && value.trim() === "") return false;
            if (Array.isArray(value) && value.length === 0) return false;
            return true;
        })
    );
}

function firstFile(section) {
    if (!Array.isArray(section.files) || !section.files.length) return null;
    return section.files.find((file) => file && file.url) || section.files[0] || null;
}

function getRequestLine(section) {
    return section && section.odoo && section.odoo.requestLine
        ? section.odoo.requestLine
        : {};
}

function boolFromOdoo(value) {
    if (value === true) return true;
    if (value === false) return false;
    const text = cleanString(value);
    if (!text) return false;
    return ["1", "true", "yes", "y", "on"].includes(text.toLowerCase());
}

function requestLineRequiresAttachment(section) {
    const requestLine = getRequestLine(section);

    if ("x_requires_attachment" in requestLine) {
        return boolFromOdoo(requestLine.x_requires_attachment);
    }

    // Safe fallback.
    // bank_information is structured-only; all other public sections currently require a file.
    return section.prefix !== "bank_information";
}

function mapGenericDocumentFields(section) {
    const prefix = section.prefix;
    const fields = section.scalarFields || {};

    return compactObject({
        x_document_number: fields[`${prefix}_document_number`] || fields[`${prefix}_number`],
        x_issuing_authority: fields[`${prefix}_issuing_authority`],
        x_place_of_issue: fields[`${prefix}_place_of_issue`],
        x_issue_date: fields[`${prefix}_date_of_issue`],
        x_expiry_date: fields[`${prefix}_date_of_expiry`],
        x_notes: fields[`${prefix}_notes`],
    });
}

function mapStructuredFields(section) {
    const fields = section.scalarFields || {};

    if (section.prefix === "qualification") {
        return compactObject({
            x_qualification_type: fields.qualification_type,
            x_qualification_subject: fields.qualification_subject,
        });
    }

    if (section.prefix === "birth_certificate") {
        return compactObject({
            x_date_of_birth: fields.date_of_birth,
            x_place_of_birth: fields.place_of_birth,
            x_country_of_birth_id: toInt(fields.country_of_birth),
        });
    }

    if (section.prefix === "family_status") {
        return compactObject({
            x_family_paper_number: fields.family_paper_number,
            x_family_reference_number: fields.family_reference_number,
            x_next_of_kin_name: fields.next_of_kin_name,
            x_next_of_kin_phone: fields.next_of_kin_phone,
        });
    }

    if (section.prefix === "health_certificate") {
        return compactObject({
            x_blood_type: fields.blood_type,
        });
    }

    if (section.prefix === "bank_information") {
        return compactObject({
            x_bank_name: fields.bank_name,
            x_bank_branch: fields.bank_branch,
            x_account_number: fields.account_number,
            x_iban: fields.iban,
            x_notes: fields.bank_notes,
        });
    }

    return {};
}

function buildWritebackItem(validatedPayload, section) {
    const routing = section.routing || {};
    const requestLine = getRequestLine(section);
    const file = firstFile(section);
    const requiresAttachment = requestLineRequiresAttachment(section);

    const applicantId = toInt(validatedPayload.request && validatedPayload.request.odooApplicantId);
    const checklistId = toInt(validatedPayload.request && validatedPayload.request.odooChecklistId);
    const requestId = toInt(validatedPayload.request && validatedPayload.request.odooRequestId);
    const requestLineId = toInt(routing.requestLineId);
    const checklistLineId = toInt(routing.checklistLineId);
    const documentTypeId = toInt(routing.documentTypeId);
    const documentCode = cleanString(routing.documentCode);

    const sourceSubmissionId = cleanString(validatedPayload.submission && validatedPayload.submission.id);
    const submittedOn = normalizeOdooDatetime(
        validatedPayload.submission && validatedPayload.submission.submissionTime
    );

    const genericFields = mapGenericDocumentFields(section);
    const structuredFields = mapStructuredFields(section);

    const fileName = cleanString(file && (file.fileName || file.name)) ||
        `${sourceSubmissionId || "fillout"}_${section.prefix}.bin`;

    const submissionVals = compactObject({
        x_applicant_id: applicantId,
        x_checklist_id: checklistId,
        x_line_id: checklistLineId,
        x_document_type_id: documentTypeId,
        x_document_code: documentCode,
        x_submission_request_id: requestId,
        x_submission_request_line_id: requestLineId,
        x_source: CONFIG.sourceSystem,
        x_source_submission_id: sourceSubmissionId,
        x_source_reference: requestLineId ? String(requestLineId) : null,
        x_state: "submitted",
        x_submitted_on: submittedOn,
        ...genericFields,
        ...structuredFields,
    });

    return {
        builder: {
            module: "required_document_writeback_build_section_items.js",
            version: CONFIG.moduleVersion,
            workflow: CONFIG.workflow,
            builtAt: new Date().toISOString(),
            probeOnlyPrefix: CONFIG.probeOnlyPrefix,
        },
        source: {
            formId: validatedPayload.form && validatedPayload.form.id,
            formName: validatedPayload.form && validatedPayload.form.name,
            filloutSubmissionId: sourceSubmissionId,
            submittedOn,
            formNotes: validatedPayload.formNotes || null,
        },
        request: {
            requestId,
            applicantId,
            checklistId,
            requestReference: validatedPayload.request && validatedPayload.request.requestReference,
            tokenReference: validatedPayload.request && validatedPayload.request.tokenReference,
        },
        section: {
            prefix: section.prefix,
            documentCode,
            requestLineId,
            checklistLineId,
            documentTypeId,
            requiresAttachment,
            hasFile: !!(file && file.url),
            hasStructuredData: !!section.hasStructuredData,
        },
        file: file ? {
            url: cleanString(file.url),
            fileName,
            mimeType: cleanString(file.mimeType) || "application/octet-stream",
            size: file.size || null,
        } : null,
        duplicateCheck: {
            model: "x_hr.applicant_required_document_submission",
            method: "search_count",
            domain: [
                ["x_source_submission_id", "=", sourceSubmissionId],
                ["x_submission_request_line_id", "=", requestLineId],
            ],
        },
        attachmentValsBase: compactObject({
            name: fileName,
            res_model: "hr.applicant",
            res_id: applicantId,
            mimetype: file ? (cleanString(file.mimeType) || "application/octet-stream") : null,
            description: `Required document submission ${section.prefix} from Fillout submission ${sourceSubmissionId}`,
            type: "binary",
        }),
        submissionVals,
        requestLineUpdateBase: {
            ids: requestLineId ? [requestLineId] : [],
            vals: {
                x_state: "submitted",
            },
        },
    };
}

const inputItems = $input.all();
const output = [];

for (const item of inputItems) {
    const payload = item && item.json ? item.json : item;

    if (!payload.validation || payload.validation.canProceed !== true) {
        continue;
    }

    const sections = Array.isArray(payload.sections) ? payload.sections : [];

    for (const section of sections) {
        if (!section || !section.routing || section.routing.show !== true) continue;
        if (!section.validation || section.validation.isValidForWriteback !== true) continue;

        if (CONFIG.probeOnlyPrefix && section.prefix !== CONFIG.probeOnlyPrefix) {
            continue;
        }

        const requiresAttachment = requestLineRequiresAttachment(section);
        const file = firstFile(section);

        if (requiresAttachment && !(file && file.url)) {
            throw new Error(`Section ${section.prefix} requires an attachment but no file URL was found.`);
        }

        if (!requiresAttachment && !section.hasPayload) {
            continue;
        }

        output.push({
            json: buildWritebackItem(payload, section),
        });
    }
}

if (!output.length) {
    throw new Error(`No writeback items were built. Probe prefix: ${CONFIG.probeOnlyPrefix || "all"}.`);
}

return output;

/**
 * MCEP / Marsellia — Required Document Writeback
 * Workflow: Marsellia | Recruitment | Required Document Submission
 * Node: Normalize Duplicate Count
 * Module: required_document_writeback_normalize_duplicate_count.js
 *
 * Pass 6C-5C:
 * - Reads the Odoo search_count response from the current HTTP item.
 * - Reattaches the paired compact writeback item from Loop Over Writeback Items.
 * - Adds duplicateCheckResult.
 *
 * Input:
 * - Current item: Odoo search_count response from Check Existing Submission Count.
 * - Linked source item: current Loop Over Writeback Items item.
 *
 * Output:
 * - Original compact writeback item plus duplicateCheckResult.
 */

const CONFIG = {
  moduleVersion: "6C-5C",
  workflow: "Marsellia | Recruitment | Required Document Submission",
  sourceNodeName: "Loop Over Writeback Items",
};

function isObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function extractCount(value) {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }

  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number.parseInt(value.trim(), 10);
    if (Number.isFinite(parsed)) return parsed;
  }

  if (Array.isArray(value)) {
    if (!value.length) return 0;

    for (const entry of value) {
      const count = extractCount(entry);
      if (count !== null) return count;
    }

    return 0;
  }

  if (isObject(value)) {
    for (const key of ["count", "result", "data", "value", "body", "duplicateCountRaw"]) {
      if (key in value) {
        const count = extractCount(value[key]);
        if (count !== null) return count;
      }
    }
  }

  return null;
}

function getSourceItem() {
  // Best path in n8n loop context:
  // use item-linking from the current HTTP response back to the current loop item.
  try {
    const linked = $(CONFIG.sourceNodeName).item;
    if (linked && linked.json) {
      return linked.json;
    }
  } catch (error) {
    // Fall through to fallback paths.
  }

  // Fallback if the HTTP node is configured to preserve input JSON.
  if ($json && $json.section && $json.duplicateCheck) {
    return $json;
  }

  throw new Error(`Could not read linked source item from node: ${CONFIG.sourceNodeName}`);
}

const source = getSourceItem();
const count = extractCount($json);

if (count === null) {
  throw new Error(`Could not extract duplicate count from HTTP response: ${JSON.stringify($json)}`);
}

return {
  json: {
    ...source,
    duplicateCheckResult: {
      module: "required_document_writeback_normalize_duplicate_count.js",
      version: CONFIG.moduleVersion,
      checkedAt: new Date().toISOString(),
      count,
      isDuplicate: count > 0,
      decision: count > 0 ? "skip_duplicate_retry" : "continue_writeback",
    },
  },
};

/**
 * MCEP / Marsellia — Required Document Writeback
 * Workflow: Marsellia | Recruitment | Required Document Submission
 * Node: Build Attachment Payload
 * Module: required_document_writeback_build_attachment_payload.js
 *
 * Pass 6C-4D:
 * - Reads the downloaded Fillout/S3 binary file.
 * - Builds Odoo ir.attachment create values.
 * - Does not write to Odoo yet.
 *
 * Input:
 * - Current item JSON from Build Writeback Items / Normalize Duplicate Count.
 * - Current item binary.submitted_file from Download Submitted File.
 *
 * Output:
 * - Same compact writeback item plus attachmentVals.
 */

const CONFIG = {
    moduleVersion: "6C-4D",
    workflow: "Marsellia | Recruitment | Required Document Submission",
};

function cleanString(value) {
    if (value === undefined || value === null) return null;
    const text = String(value).trim();
    return text || null;
}

function safeString(value) {
    return cleanString(value)
        ? cleanString(value).replace(/[^A-Za-z0-9_.-]+/g, "_").replace(/_+/g, "_")
        : null;
}

function extensionFromMimeType(mimeType) {
    const mime = cleanString(mimeType);
    if (!mime) return null;

    const map = {
        "application/pdf": "pdf",
        "image/jpeg": "jpg",
        "image/png": "png",
        "image/webp": "webp",
    };

    return map[mime] || null;
}

function extensionFromName(fileName) {
    const name = cleanString(fileName);
    if (!name || !name.includes(".")) return null;
    const ext = name.split(".").pop().toLowerCase();
    return ext && ext.length <= 8 ? ext : null;
}

function getInputItem() {
    try {
        if ($input && $input.item) return $input.item;
    } catch (error) {
        // ignored
    }

    return {};
}

function getBinaryFile(item) {
    const binary = item && item.binary ? item.binary : {};

    if (binary.submitted_file) return binary.submitted_file;

    const keys = Object.keys(binary || {});
    if (!keys.length) return null;

    return binary[keys[0]];
}

function binaryToBase64(binaryFile) {
    if (!binaryFile) return null;

    if (typeof binaryFile.data === "string" && binaryFile.data.trim()) {
        return binaryFile.data;
    }

    if (typeof binaryFile.fileData === "string" && binaryFile.fileData.trim()) {
        return binaryFile.fileData;
    }

    if (Buffer.isBuffer(binaryFile)) {
        return binaryFile.toString("base64");
    }

    return null;
}

function buildSafeFileName(json, binaryFile) {
    const requestReference = safeString(json.request && json.request.requestReference) || "MCEP-F0003-REQ";
    const prefix = safeString(json.section && json.section.prefix) || "document";
    const sourceSubmissionId = safeString(json.source && json.source.filloutSubmissionId) || "fillout";

    const ext =
        extensionFromName(binaryFile && (binaryFile.fileName || binaryFile.filename)) ||
        extensionFromName(json.file && json.file.fileName) ||
        extensionFromMimeType(binaryFile && binaryFile.mimeType) ||
        extensionFromMimeType(json.file && json.file.mimeType) ||
        "bin";

    return `${requestReference}_${prefix}_${sourceSubmissionId}.${ext}`;
}

const item = getInputItem();
const json = item && item.json ? item.json : $json;
const binaryFile = getBinaryFile(item);
const base64 = binaryToBase64(binaryFile);

if (!json || !json.section) {
    throw new Error("Missing compact writeback item JSON.");
}

if (!binaryFile) {
    throw new Error("Missing binary file. Expected binary.submitted_file from Download Submitted File.");
}

if (!base64) {
    throw new Error("Downloaded binary file does not contain base64 data.");
}

const detectedMimeType =
    cleanString(binaryFile.mimeType) ||
    cleanString(binaryFile.mimetype) ||
    cleanString(json.file && json.file.mimeType) ||
    "application/octet-stream";

const safeFileName = buildSafeFileName(json, binaryFile);

const originalFileName =
    cleanString(binaryFile.fileName) ||
    cleanString(binaryFile.filename) ||
    cleanString(json.file && json.file.fileName);

const attachmentVals = {
    ...(json.attachmentValsBase || {}),
    name: safeFileName,
    res_model: "hr.applicant",
    res_id: json.request.applicantId,
    mimetype: detectedMimeType,
    type: "binary",
    datas: base64,
    description: [
        `Required document submission: ${json.section.prefix}`,
        `Fillout submission: ${json.source.filloutSubmissionId}`,
        originalFileName ? `Original filename: ${originalFileName}` : null,
    ].filter(Boolean).join("\n"),
};

return {
    json: {
        ...json,
        attachmentPayload: {
            module: "required_document_writeback_build_attachment_payload.js",
            version: CONFIG.moduleVersion,
            builtAt: new Date().toISOString(),
            binaryPropertyFound: "submitted_file",
            originalFileName,
            safeFileName,
            mimeType: detectedMimeType,
            base64Length: base64.length,
        },
        attachmentVals,
    },
};

/**
 * MCEP / Marsellia — Required Document Writeback
 * Workflow: Marsellia | Recruitment | Required Document Submission
 * Node: Build Submission Payload
 * Module: required_document_writeback_build_submission_payload.js
 *
 * Pass 6C-4F:
 * - Reads created ir.attachment ID from Create Odoo Attachment.
 * - Reattaches compact writeback item from Build Attachment Payload.
 * - Adds x_attachment_id to x_hr.applicant_required_document_submission create values.
 * - Does not write the submission yet.
 */

const CONFIG = {
    moduleVersion: "6C-5D",
    workflow: "Marsellia | Recruitment | Required Document Submission",
    sourceNodeName: "Build Attachment Payload",
};

function isObject(value) {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

function extractCreatedId(value) {
    if (typeof value === "number" && Number.isFinite(value)) {
        return value;
    }

    if (typeof value === "string" && /^\d+$/.test(value.trim())) {
        return Number.parseInt(value.trim(), 10);
    }

    if (Array.isArray(value)) {
        for (const entry of value) {
            const id = extractCreatedId(entry);
            if (id) return id;
        }
    }

    if (isObject(value)) {
        for (const key of ["id", "result", "data", "value", "body"]) {
            if (key in value) {
                const id = extractCreatedId(value[key]);
                if (id) return id;
            }
        }
    }

    return null;
}

function getSourceItem() {
    // Best path inside Loop Over Items: linked item from the previous node.
    try {
        const linked = $(CONFIG.sourceNodeName).item;
        if (linked && linked.json) {
            return linked.json;
        }
    } catch (error) {
        // Fall through to fallback path.
    }

    // Fallback for non-loop/manual testing.
    try {
        const sourceItems = $items(CONFIG.sourceNodeName);
        if (sourceItems && sourceItems.length) {
            return sourceItems[0].json || sourceItems[0];
        }
    } catch (error) {
        // Fall through.
    }

    throw new Error(`Could not read linked source item from node: ${CONFIG.sourceNodeName}`);
}


const source = getSourceItem();
const attachmentResponse = $json;
const attachmentId = extractCreatedId(attachmentResponse);

if (!attachmentId) {
    throw new Error(`Could not extract created attachment ID from response: ${JSON.stringify(attachmentResponse)}`);
}

if (!source.submissionVals) {
    throw new Error("Missing submissionVals from source writeback item.");
}

const submissionVals = {
    ...source.submissionVals,
    x_attachment_id: attachmentId,
};

return {
    json: {
        ...source,
        submissionPayload: {
            module: "required_document_writeback_build_submission_payload.js",
            version: CONFIG.moduleVersion,
            builtAt: new Date().toISOString(),
            attachmentId,
            model: "x_hr.applicant_required_document_submission",
            method: "create",
        },
        attachmentId,
        submissionVals,
    },
};

